(() => {
  const WINDOW_MS = 6e5;
  const MAX_IN_WINDOW = 5;
  function checkCardPayments(input) {
    for (const name of Object.keys(input)) {
      if (name !== "paymentTimes") {
        throw new Error("unknown field: " + name);
      }
    }
    const paymentTimes = input.paymentTimes;
    const times = paymentTimes.map((s) => Date.parse(s));
    let left = 0;
    for (let i = 0; i < times.length; i++) {
      while (times[i] - times[left] >= WINDOW_MS) {
        left++;
      }
      if (i - left + 1 > MAX_IN_WINDOW) {
        return { alert: true, alertTime: paymentTimes[i] };
      }
    }
    return { alert: false, alertTime: null };
  }
  return { checkCardPayments };
})()

