build.unitScript:
const t = (hm) => "2024-01-01T" + hm + ":00Z";
const run = (list) => code.checkCardPayments({ paymentTimes: list.map(t) });
test("six payments within 9 minutes raise an alert at the sixth payment time (AC-1)", () => {
  assert.deepEqual(run(["10:00", "10:02", "10:04", "10:06", "10:08", "10:09"]), { alert: true, alertTime: t("10:09") });
});
test("payments exactly 10 minutes apart are in different periods so no alert (AC-2)", () => {
  assert.deepEqual(run(["10:00", "10:02", "10:04", "10:06", "10:08", "10:10"]), { alert: false, alertTime: null });
});
test("only five payments raise no alert (AC-3)", () => {
  assert.deepEqual(run(["10:00", "10:02", "10:04", "10:06", "10:08"]), { alert: false, alertTime: null });
});
test("the period slides with each payment, so six payments from 10:11 to 10:16 alert at 10:16", () => {
  assert.deepEqual(run(["10:00", "10:05", "10:11", "10:12", "10:13", "10:14", "10:15", "10:16"]), { alert: true, alertTime: t("10:16") });
});
test("an empty list of payments raises no alert", () => {
  assert.deepEqual(code.checkCardPayments({ paymentTimes: [] }), { alert: false, alertTime: null });
});
test("an input field other than paymentTimes is rejected with an unknown field error", () => {
  assert.throws(() => code.checkCardPayments({ paymentTimes: [], account: "A1" }), /unknown field: account/);
});

build.testScript:
test("six payments inside ten minutes alert at the sixth time", function() {
  var actual = code.checkCardPayments({
    paymentTimes: [
      "2024-01-01T10:00:00Z",
      "2024-01-01T10:02:00Z",
      "2024-01-01T10:04:00Z",
      "2024-01-01T10:06:00Z",
      "2024-01-01T10:08:00Z",
      "2024-01-01T10:09:00Z"
    ]
  });
  assert.deepEqual(actual, { alert: true, alertTime: "2024-01-01T10:09:00Z" });
});
test("payments exactly ten minutes apart are not in the same period", function() {
  var actual = code.checkCardPayments({
    paymentTimes: [
      "2024-01-01T10:00:00Z",
      "2024-01-01T10:02:00Z",
      "2024-01-01T10:04:00Z",
      "2024-01-01T10:06:00Z",
      "2024-01-01T10:08:00Z",
      "2024-01-01T10:10:00Z"
    ]
  });
  assert.deepEqual(actual, { alert: false, alertTime: null });
});
test("five payments do not raise an alert", function() {
  var actual = code.checkCardPayments({
    paymentTimes: [
      "2024-01-01T10:00:00Z",
      "2024-01-01T10:02:00Z",
      "2024-01-01T10:04:00Z",
      "2024-01-01T10:06:00Z",
      "2024-01-01T10:08:00Z"
    ]
  });
  assert.deepEqual(actual, { alert: false, alertTime: null });
});
test("no payments raise no alert", function() {
  var actual = code.checkCardPayments({ paymentTimes: [] });
  assert.deepEqual(actual, { alert: false, alertTime: null });
});
test("six payments spaced nine minutes apart do not raise an alert", function() {
  var actual = code.checkCardPayments({
    paymentTimes: [
      "2024-01-01T10:00:00Z",
      "2024-01-01T10:09:00Z",
      "2024-01-01T10:18:00Z",
      "2024-01-01T10:27:00Z",
      "2024-01-01T10:36:00Z",
      "2024-01-01T10:45:00Z"
    ]
  });
  assert.deepEqual(actual, { alert: false, alertTime: null });
});
test("the sixth payment in a window that starts after an earlier payment alerts at that time", function() {
  var actual = code.checkCardPayments({
    paymentTimes: [
      "2024-01-01T10:05:00Z",
      "2024-01-01T10:06:00Z",
      "2024-01-01T10:07:00Z",
      "2024-01-01T10:08:00Z",
      "2024-01-01T10:09:00Z",
      "2024-01-01T10:14:00Z"
    ]
  });
  assert.deepEqual(actual, { alert: true, alertTime: "2024-01-01T10:14:00Z" });
});
test("alert time is the payment that first makes a period hold six payments", function() {
  var actual = code.checkCardPayments({
    paymentTimes: [
      "2024-01-01T10:00:00Z",
      "2024-01-01T10:05:00Z",
      "2024-01-01T10:10:00Z",
      "2024-01-01T10:11:00Z",
      "2024-01-01T10:12:00Z",
      "2024-01-01T10:13:00Z",
      "2024-01-01T10:14:00Z"
    ]
  });
  assert.deepEqual(actual, { alert: true, alertTime: "2024-01-01T10:14:00Z" });
});
test("an unknown input field throws unknown field with that name", function() {
  assert.throws(function() {
    code.checkCardPayments({ paymentTimes: [], accountId: "a1" });
  }, /unknown field: accountId/);
});

